import sys

def main():
    input_line = sys.stdin.readline().strip()
    n, mod = map(int, input_line.split())

    dp = [[0] * (n * n + 5) for _ in range(n)]
    dp[0][0] = 1

    for i in range(1, n):
        for j in range(len(dp[0])):
            for c in range(i + 1):
                if j - c >= 0:
                    dp[i][j] += dp[i - 1][j - c]
                    dp[i][j] %= mod
                    if dp[i][j] == 0:
                        dp[i][j] += mod

    sums = [[0] * len(dp[0]) for _ in range(n)]
    for i in range(n):
        runningSum = 0
        for j in range(len(dp[0])):
            runningSum += dp[i][j]
            runningSum %= mod
            if runningSum == 0:
                runningSum += mod
            sums[i][j] = runningSum

    factorial = [1] * (501 * 501)
    for i in range(1, len(factorial)):
        factorial[i] = (factorial[i - 1] * i) % mod

    nCr = [[0] * 501 for _ in range(501)]
    nCr[0][0] = 1
    for i in range(1, 501):
        nCr[i][0] = 1
        for j in range(1, 501):
            nCr[i][j] = (nCr[i - 1][j] + nCr[i - 1][j - 1]) % mod
            if nCr[i][j] == 0:
                nCr[i][j] += mod

    totalRes = 0
    for i in range(n - 2, -1, -1):
        cnt = n - i
        pre = n - cnt
        comb = (nCr[n][pre] * factorial[pre]) % mod
        if comb == 0:
            comb += mod
        total = 0
        for dif in range(1, cnt):
            for inv in range(dif, len(dp[0])):
                if dp[cnt - 2][inv] == 0:
                    break
                if inv - dif - 1 < 0:
                    continue
                x = dp[cnt - 2][inv]
                y = sums[cnt - 2][inv - dif - 1]
                x = (x * y) % mod
                if x == 0:
                    x += mod
                total += (x * (cnt - dif)) % mod
                total %= mod
        totalRes += (total * comb) % mod
        totalRes %= mod
        if totalRes == 0:
            totalRes += mod

    print(totalRes % mod)

if __name__ == "__main__":
    main()

